    '<meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<style>' + STYLE + (extraStyle || "") + '</style></head>' +
    '<body style="margin:0;background:transparent">' +
    '<div class="fz-orch" data-theme="' + theme + '" style="padding:14px">' + inner + '</div>' +
    '</body></html>';
  return { section: section, dashboardUri: "data:text/html;charset=utf-8," + encodeURIComponentPolyfill(html) };
}
function themeOf(ctx) {
  return String((ctx && ctx.themeMode) || "Dark").toLowerCase() === "light" ? "light" : "dark";
}
function stateColors(state) {
  if (state === "down") return { c: "var(--down)", lbl: "Down" };
  if (state === "idle") return { c: "var(--idle)", lbl: "Idle" };
  return { c: "var(--running)", lbl: "Running" };
}
const ABBR_BG = ["#7c5cff", "#22a7f0", "#f0883e", "#19c39c", "#e8568a", "#9d7bff"];
const TOPO_SC = { running: "#1f9d63", idle: "#fd8b09", down: "#dc3b4b", setup: "#2a74d6" };
// d = { counts, errors, queue, spark, latency } — each a Connection (or null)
function buildTypeStats(d, nowMs, th) {
  th = th || { downRate: 0.25, downMin: 5, idleMins: 30 };
  const byType = {};
  const ensure = (t) => (byType[t] = byType[t] ||
    { type: t, count: 0, errors: 0, queue: 0, last: null, dirs: {}, spark: [], latSum: 0, latN: 0 });
  edges(d.counts).forEach((n) => {
    const t = n.metadata && n.metadata.integrationType; if (!t) return;
    const s = ensure(t);
    s.count += aggCount(n);
    const mx = aggMax(n, "processedAt"); if (mx && (!s.last || mx > s.last)) s.last = mx;
    if (n.metadata && n.metadata.isInbound != null) s.dirs[n.metadata.isInbound ? "in" : "out"] = true;
  });
  edges(d.errors).forEach((n) => {
    const t = n.metadata && n.metadata.integrationType; if (!t) return;
    ensure(t).errors += aggCount(n);
  });
  edges(d.queue).forEach((n) => {
    const t = n.metadata && n.metadata.integrationType; if (!t) return;
    ensure(t).queue += aggCount(n);
  });
  edges(d.spark).forEach((n) => {
    const t = n.metadata && n.metadata.integrationType; if (!t) return;
    ensure(t).spark.push(aggCount(n));
  });
  edges(d.latency).forEach((n) => {
    const t = n.metadata && n.metadata.integrationType; if (!t || !n.createdAt || !n.processedAt) return;
    const s = ensure(t);
    s.latSum += new Date(n.processedAt).getTime() - new Date(n.createdAt).getTime();
    s.latN += 1;
  });
  let i = 0;
  return Object.keys(byType).sort().map((t) => {
    const s = byType[t];
    const errorRate = s.count ? s.errors / s.count : 0;
    const minsSinceLast = s.last ? (nowMs - new Date(s.last).getTime()) / 60000 : Infinity;
    let state = "running";
    if (errorRate >= th.downRate && s.count >= th.downMin) state = "down";
    else if (minsSinceLast > th.idleMins) state = "idle";
    const dirKeys = Object.keys(s.dirs);
    const dir = dirKeys.length > 1 ? "bi" : (dirKeys[0] || "bi");
    return {
      type: t, name: t, abbr: initials(t), abbrBg: ABBR_BG[(i++) % ABBR_BG.length],
      count: s.count, errors: s.errors, queue: s.queue,
      success: s.count ? ((s.count - s.errors) / s.count) * 100 : 100,
      latency: s.latN ? s.latSum / s.latN : 0,
      spark: s.spark.length ? s.spark : [s.count],
      last: s.last, errorRate: errorRate, state: state, dir: dir
    };
  });
}
function renderHeader($in, ctx) {
  let total = 0;
  edges($in.statusCounts).forEach((n) => { total += aggCount(n); });
  const failed = ($in.failed && $in.failed.total) || 0;
  const success = total ? ((total - failed) / total) * 100 : 100;
  let ls = 0, ln = 0;
  edges($in.latencySample).forEach((n) => {
    if (n.createdAt && n.processedAt) { ls += new Date(n.processedAt).getTime() - new Date(n.createdAt).getTime(); ln++; }
  });
  const avgLatency = ln ? ls / ln : 0;
  const flows = ($in.activeFlows && $in.activeFlows.total) || 0;
  const __ds = (ctx.window && ctx.window.dayStartIso) || ctx.dayStartIso;
  const __de = (ctx.window && ctx.window.dayEndIso) || ctx.dayEndIso;
  const mins = Math.max(1, ((__de ? new Date(__de).getTime() : Date.now()) - (__ds ? new Date(__ds).getTime() : Date.now() - 86400000)) / 60000);
  const tputRate = total / mins;
  const cards = [
    { lbl: "Messages (24H)", val: fmtNum(total), sub: fmtNum(tputRate) + " msg/min", ac: "var(--accent)" },
    { lbl: "Success rate", val: fmtPct(success), sub: fmtNum(total - failed) + " ok", ac: "var(--ok)" },
    { lbl: "Failed (24H)", val: fmtNum(failed), sub: failed ? "needs attention" : "all clear", ac: failed ? "var(--err)" : "var(--ok)" },
    { lbl: "Avg latency", val: fmtMs(avgLatency), sub: "create → processed", ac: "var(--info)" },
    { lbl: "Active flows", val: String(flows), sub: "integration configs", ac: "var(--accent2)" }
  ];
  return `<div class="kpis">` + cards.map((c) =>
    `<div class="kpi" style="position:relative;overflow:hidden;border-top:3px solid ${c.ac}">
       <div class="lbl" style="display:flex;align-items:center;gap:7px"><span style="width:7px;height:7px;border-radius:999px;background:${c.ac}"></span>${esc(c.lbl)}</div>
       <div class="val" style="color:${c.ac}">${esc(c.val)}</div><div class="sub">${esc(c.sub)}</div></div>`).join("") + `</div>`;
}
var __ctx = ($state && $state.context && $state.context.REQUEST) || {};
return buildDoc("header", themeOf(__ctx), renderHeader($$ || {}, __ctx));

data.query:
query ($s: DateTime, $e: DateTime, $errorState: [String!]) {
  byType: integrationStaging(
    where: { processedAt: { _gte: $s, _lt: $e } }
    orderBy: [{ field: integrationConfigId, direction: asc }]
  ) {
    edges {
      node {
        integrationConfig {
          integrationTypeId
          isInbound
        }
        _aggregate {
          id {
            count
          }
          processedAt {
            maximum
          }
        }
      }
    }
  }
  errorsByType: integrationStaging(
    where: {
      processedAt: { _gte: $s, _lt: $e }
      _or: [
        { statusId: { _in: $errorState } }
        { appPostError: { _eq: true } }
      ]
    }
    orderBy: [{ field: integrationConfigId, direction: asc }]
  ) {
    edges {
      node {
        integrationConfig {
          integrationTypeId
        }
        _aggregate {
          id {
            count
          }
        }
      }
    }
  }
  latencySample: integrationStaging(
    orderBy: [{ field: processedAt, direction: desc }]
    first: 1000
  ) {
    edges {
      node {
        createdAt
        processedAt
        integrationConfig {
          integrationTypeId
        }
      }
    }
  }

  configs: integrationConfiguration(where: { active: { _eq: true } }, first: 500) {
    edges { node { integrationTypeId isInbound } }
  }
}

