    : `<div class="muted" style="font-size:13px">No field mapping in config parameters. Config summary:</div>
       <div style="margin-top:8px;font-size:13px">
         <div>Active: <b>${cfg.active ? "Yes" : "No"}</b> · Direction: <b>${cfg.isInbound ? "Inbound" : "Outbound"}</b></div>
         <div>Max retries: <b>${esc(cfg.maxRetryAttemps != null ? cfg.maxRetryAttemps : "—")}</b> · Batch: <b>${esc(cfg.maxRecords != null ? cfg.maxRecords : "—")}</b></div>
       </div>`;
