    <div class="row" style="justify-content:space-between;align-items:flex-start">
      <div class="row" style="gap:12px">
        <div class="abbr" style="background:${ABBR_BG[0]}">${esc(initials(type))}</div>
        <div><h3>${esc(type)}</h3>
          <div class="muted" style="font-size:12px">${esc(cfg.name || "Integration connector")}</div></div>
      </div>
      <div class="row" style="gap:18px">
        <div><div class="tag">Success</div><div style="font-size:18px;font-weight:800">${fmtPct(success)}</div></div>
        <div><div class="tag">Latency</div><div style="font-size:18px;font-weight:800">${fmtMs(ln ? ls / ln : 0)}</div></div>
        <div><div class="tag">Recent</div><div style="font-size:18px;font-weight:800">${total}</div></div>
      </div>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:18px">
      <div><div class="tag" style="margin-bottom:8px">Field mapping</div>${mappingBlock}</div>
      <div><div class="tag" style="margin-bottom:8px">Recent runs</div>
        <table class="q"><tbody>${runRows || '<tr><td class="muted">No runs.</td></tr>'}</tbody></table></div>
