  const T = themeOf(ctx) === "light"
    ? { bg: "var(--panel)", chip: "#f3f4fb", chipStroke: "#dadcec",
        name: "#1b1730", sub: "#6b6490", plate: "#5b30df", plateStroke: "#4a27c0", hubText: "#ffffff", hubLabel: "#8a85a6" }
    : { bg: "radial-gradient(circle at 50% 42%,#231f37 0%,#16141f 100%)", chip: "#26233a", chipStroke: "#3d3a54",
        name: "#f6f5fa", sub: "#918ea6", plate: "#ffffff", plateStroke: "#e6ddfc", hubText: "#5b30df", hubLabel: "#bab7c9" };
