    const outP = "M" + cx + "," + cy + " L" + nd.x.toFixed(1) + "," + nd.y.toFixed(1);
    const inP = "M" + nd.x.toFixed(1) + "," + nd.y.toFixed(1) + " L" + cx + "," + cy;
    const cfg = nd.state === "running" ? { n: 3, dur: 1.7, r: 3.4 }
