      const path = dir === "out" ? outP : inP;
      for (let k = 0; k < cfg.n; k++) {
        out += `<circle r="${cfg.r}" fill="${col}" style="filter:drop-shadow(0 0 4px ${col})">
          <animateMotion dur="${cfg.dur}s" repeatCount="indefinite" path="${path}"
            begin="${(k * cfg.dur / cfg.n).toFixed(2)}s"/></circle>`;
      }
    });
