  }).join("");
  const rings = [0, 1].map((i) =>
    `<circle cx="${cx}" cy="${cy}" r="58" fill="none" stroke="#7c5cf0" stroke-width="1.5" opacity="0.5">
       <animate attributeName="r" values="58;134" dur="3.4s" begin="${i * 1.7}s" repeatCount="indefinite"/>
       <animate attributeName="opacity" values="0.55;0" dur="3.4s" begin="${i * 1.7}s" repeatCount="indefinite"/>
     </circle>`).join("");
  const hub =
    `<circle cx="${cx}" cy="${cy}" r="104" fill="url(#hubGlow)"/>${rings}
     <rect x="${cx - 50}" y="${cy - 50}" width="100" height="100" rx="26" fill="${T.plate}" stroke="${T.plateStroke}"
       stroke-width="1.5" style="filter:drop-shadow(0 10px 28px rgba(91,48,223,0.5))"/>
     <text x="${cx}" y="${cy + 7}" text-anchor="middle" fill="${T.hubText}" font-size="20" font-weight="800"
       font-family="-apple-system,BlinkMacSystemFont,sans-serif">FUUZ</text>
     <text x="${cx}" y="${cy + 80}" text-anchor="middle" fill="${T.hubLabel}" font-size="11" font-weight="700"
       letter-spacing="0.16em" font-family="-apple-system,BlinkMacSystemFont,sans-serif">INTEGRATION HUB</text>`;
  const w = 158, hh = 52;
  const chips = placed.map((nd) => {
    const col = TOPO_SC[nd.state] || TOPO_SC.running;
    const down = nd.state === "down";
    const gx = nd.x - w / 2, gy = nd.y - hh / 2;
    const sub = down ? "Connection error" : (fmtNum(nd.count) + " msgs · " + fmtMs(nd.latency));
    const pulse = nd.state === "running"
      ? `<animate attributeName="opacity" values="1;0.35;1" dur="1.6s" repeatCount="indefinite"/>` : "";
    return `<g transform="translate(${gx.toFixed(1)},${gy.toFixed(1)})">
        <rect x="0" y="0" width="${w}" height="${hh}" rx="12" fill="${T.chip}"
          stroke="${down ? col : T.chipStroke}" stroke-width="${down ? 1.5 : 1}"
          ${down ? `style="filter:drop-shadow(0 0 11px ${col}99)"` : ""}/>
        <rect x="9" y="9" width="34" height="34" rx="8" fill="${col}22" stroke="${col}66" stroke-width="1"/>
        <text x="26" y="31" text-anchor="middle" fill="${col}" font-size="12.5" font-weight="800"
          font-family="-apple-system,BlinkMacSystemFont,sans-serif">${esc(nd.abbr)}</text>
        <text x="51" y="23" fill="${T.name}" font-size="12.5" font-weight="700"
          font-family="-apple-system,BlinkMacSystemFont,sans-serif">${esc(nd.name)}</text>
        <text x="51" y="39" fill="${T.sub}" font-size="10.5"
          font-family="-apple-system,BlinkMacSystemFont,sans-serif">${esc(sub)}</text>
