      <span class="row" style="gap:6px"><span class="dot" style="background:#1f9d63"></span>Running</span>
      <span class="row" style="gap:6px"><span class="dot" style="background:#fd8b09"></span>Idle</span>
      <span class="row" style="gap:6px"><span class="dot" style="background:#dc3b4b"></span>Down</span></div>`;
  return `<div class="fz-card" style="background:${T.bg}">
    <div class="row" style="justify-content:space-between;margin-bottom:6px">
      <div><div class="fz-card__title">Integration topology</div>
        <div class="muted" style="font-size:13px;margin-top:3px">Hub-and-spoke data flow · ${healthy}/${stats.length} connectors healthy</div></div>
      ${legend}
    </div>
    <svg viewBox="0 0 ${VBW} ${VBH}" width="100%" preserveAspectRatio="xMidYMid meet" style="display:block;height:auto">
      ${defs}${spokeLines}${packets}${hub}${chips}
    </svg></div>`;
}
var __ctx = ($state && $state.context && $state.context.REQUEST) || {};
return buildDoc("topology", themeOf(__ctx), renderTopology($$ || {}, __ctx));

data.query:
query ($s: DateTime, $errorState: [String!]) {
  buckets: integrationStaging(
    where: { processedAt: { _gte: $s } }
    orderBy: [{ field: processedAt, direction: asc }]
  ) {
    edges {
      node {
        processedAt(round: { unit: minute })
        _aggregate {
          id {
            count
          }
        }
      }
    }
  }
  errorBuckets: integrationStaging(
    where: {
      processedAt: { _gte: $s }
      _or: [
        { statusId: { _in: $errorState } }
        { appPostError: { _eq: true } }
      ]
    }
    orderBy: [{ field: processedAt, direction: asc }]
  ) {
    edges {
      node {
        processedAt(round: { unit: minute })
        _aggregate {
          id {
            count
          }
        }
      }
    }
  }
}

data.transform:
function esc(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}
function initials(name) {
  const parts = String(name || "?").trim().split(/\s+/);
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[1][0]).toUpperCase();
}
function fmtNum(n) {
  n = Number(n) || 0;
  if (n >= 1e6) return (n / 1e6).toFixed(2) + "M";
  if (n >= 1e3) return (n / 1e3).toFixed(1) + "k";
  return String(Math.round(n));
}
function fmtInt(n) { return (Math.round(Number(n) || 0)).toLocaleString("en-US"); }
function fmtPct(n, d) { return (Number(n) || 0).toFixed(d == null ? 1 : d) + "%"; }
function fmtMs(ms) {
  ms = Math.round(Number(ms) || 0);
  return ms >= 1000 ? (ms / 1000).toFixed(2) + "s" : ms + "ms";
}
function relTime(iso, nowMs) {
  if (!iso) return "—";
  const diff = Math.max(0, ((nowMs || Date.now()) - new Date(iso).getTime()) / 1000);
  if (diff < 60) return Math.round(diff) + "s ago";
  if (diff < 3600) return Math.round(diff / 60) + "m ago";
  if (diff < 86400) return Math.round(diff / 3600) + "h ago";
  return Math.round(diff / 86400) + "d ago";
}
function sparkPath(vals, w, h) {
  const a = (vals && vals.length ? vals : [0]).map((v) => Number(v) || 0);
  const max = Math.max.apply(null, a) || 1;
  const min = Math.min.apply(null, a);
  const span = (max - min) || 1;
  const step = a.length > 1 ? w / (a.length - 1) : 0;
  return a.map((v, i) => {
    const x = (i * step).toFixed(1);
    const y = (h - ((v - min) / span) * h).toFixed(1);
    return (i === 0 ? "M" : "L") + x + " " + y;
  }).join(" ");
}
function hhmm(iso, tz) {
  if (!iso) return "";
  try { return new Intl.DateTimeFormat("en-US", { timeZone: tz || "UTC", hour: "2-digit", minute: "2-digit", hour12: false }).format(new Date(iso)); }
  catch (e) { return ""; }
}
function edges(conn) {
  return (conn && conn.edges ? conn.edges : []).map((e) => e && e.node).filter(Boolean);
}
function aggCount(node) {
  return (node && node._aggregate && node._aggregate.id && node._aggregate.id.count) || 0;
}
function aggMax(node, field) {
  const a = node && node._aggregate && node._aggregate[field];
  if (!a) return null;
  const m = a.maximum;
  return Array.isArray(m) ? m[0] : m;
}
const STYLE = `
