.dot{width:9px;height:9px;border-radius:999px;display:inline-block}
.pill{display:inline-flex;align-items:center;gap:6px;font-size:11px;font-weight:700;
  text-transform:uppercase;letter-spacing:.05em;padding:3px 9px;border-radius:999px}
.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}
.kpi{background:var(--panel);border:1px solid var(--border);border-radius:16px;padding:16px 18px}
.kpi .lbl{font-size:11px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.kpi .val{font-size:30px;font-weight:800;margin-top:6px;font-variant-numeric:tabular-nums}
.kpi .sub{font-size:12px;color:var(--muted);margin-top:4px}
.cgrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:14px}
.conn{background:var(--panel);border:1px solid var(--border);border-radius:16px;padding:16px;cursor:pointer;
  transition:transform .12s,border-color .12s}
.conn:hover{transform:translateY(-2px);border-color:var(--accent)}
.abbr{width:40px;height:40px;border-radius:11px;display:flex;align-items:center;justify-content:center;
  font-weight:800;font-size:14px;color:#fff}
.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:14px}
.metric .m-v{font-size:17px;font-weight:800;font-variant-numeric:tabular-nums}
.metric .m-l{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em}
.feed{display:flex;flex-direction:column;gap:2px}
.ev{display:flex;gap:11px;align-items:flex-start;padding:9px 6px;border-bottom:1px solid var(--border)}
.ev:last-child{border-bottom:0}
.ev .txt{font-size:13px;line-height:1.35}
.ev .meta{font-size:11px;color:var(--muted);margin-top:2px}
table.q{width:100%;border-collapse:collapse;font-size:13px}
table.q th{text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.05em;
  color:var(--muted);padding:8px 10px;border-bottom:1px solid var(--border)}
table.q td{padding:9px 10px;border-bottom:1px solid var(--border)}
.modal h3{font-size:18px;font-weight:800}
.tag{font-size:11px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.05em}
`;
// Percent-encoding polyfill — the sandbox has no encodeURIComponent / btoa.
function encodeURIComponentPolyfill(str) {
  const unreserved = {};
  const safe = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.~";
  for (let i = 0; i < safe.length; i++) unreserved[safe.charCodeAt(i)] = true;
  const out = [];
  const hex = (n) => { const h = n.toString(16).toUpperCase(); return h.length === 1 ? "0" + h : h; };
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    if (c < 0x80) out.push(unreserved[c] ? str.charAt(i) : "%" + hex(c));
    else if (c < 0x800) out.push("%" + hex(0xC0 | (c >> 6)) + "%" + hex(0x80 | (c & 0x3F)));
    else if (c >= 0xD800 && c <= 0xDBFF) {
      const next = str.charCodeAt(i + 1);
      const cp = 0x10000 + ((c & 0x3FF) << 10) + (next & 0x3FF); i++;
      out.push("%" + hex(0xF0 | (cp >> 18)) + "%" + hex(0x80 | ((cp >> 12) & 0x3F)) +
               "%" + hex(0x80 | ((cp >> 6) & 0x3F)) + "%" + hex(0x80 | (cp & 0x3F)));
    } else out.push("%" + hex(0xE0 | (c >> 12)) + "%" + hex(0x80 | ((c >> 6) & 0x3F)) + "%" + hex(0x80 | (c & 0x3F)));
  }
  return out.join("");
}
// Builds a COMPLETE HTML document for one section and returns it as a data URI
// for binding to a webpage element's `path`. Returns { section, dashboardUri }.
function buildDoc(section, theme, inner, extraStyle) {
  const html =
    '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8">' +
    '<meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<style>' + STYLE + (extraStyle || "") + '</style></head>' +
    '<body style="margin:0;background:transparent">' +
    '<div class="fz-orch" data-theme="' + theme + '" style="padding:14px">' + inner + '</div>' +
    '</body></html>';
  return { section: section, dashboardUri: "data:text/html;charset=utf-8," + encodeURIComponentPolyfill(html) };
}
function themeOf(ctx) {
  return String((ctx && ctx.themeMode) || "Dark").toLowerCase() === "light" ? "light" : "dark";
}
function stateColors(state) {
  if (state === "down") return { c: "var(--down)", lbl: "Down" };
  if (state === "idle") return { c: "var(--idle)", lbl: "Idle" };
  return { c: "var(--running)", lbl: "Running" };
}
const ABBR_BG = ["#7c5cff", "#22a7f0", "#f0883e", "#19c39c", "#e8568a", "#9d7bff"];
const TOPO_SC = { running: "#1f9d63", idle: "#fd8b09", down: "#dc3b4b", setup: "#2a74d6" };
// d = { counts, errors, queue, spark, latency } — each a Connection (or null)
function buildTypeStats(d, nowMs, th) {
  th = th || { downRate: 0.25, downMin: 5, idleMins: 30 };
  const byType = {};
  const ensure = (t) => (byType[t] = byType[t] ||
    { type: t, count: 0, errors: 0, queue: 0, last: null, dirs: {}, spark: [], latSum: 0, latN: 0 });
  edges(d.counts).forEach((n) => {
    const t = n.integrationConfig && n.integrationConfig.integrationTypeId; if (!t) return;
    const s = ensure(t);
    s.count += aggCount(n);
    const mx = aggMax(n, "processedAt"); if (mx && (!s.last || mx > s.last)) s.last = mx;
    if (n.integrationConfig && n.integrationConfig.isInbound != null) s.dirs[n.integrationConfig.isInbound ? "in" : "out"] = true;
  });
  edges(d.errors).forEach((n) => {
    const t = n.integrationConfig && n.integrationConfig.integrationTypeId; if (!t) return;
    ensure(t).errors += aggCount(n);
  });
  edges(d.queue).forEach((n) => {
    const t = n.integrationConfig && n.integrationConfig.integrationTypeId; if (!t) return;
    ensure(t).queue += aggCount(n);
  });
  edges(d.spark).forEach((n) => {
    const t = n.integrationConfig && n.integrationConfig.integrationTypeId; if (!t) return;
    ensure(t).spark.push(aggCount(n));
  });
  edges(d.latency).forEach((n) => {
    const t = n.integrationConfig && n.integrationConfig.integrationTypeId; if (!t || !n.createdAt || !n.processedAt) return;
    const s = ensure(t);
    s.latSum += new Date(n.processedAt).getTime() - new Date(n.createdAt).getTime();
    s.latN += 1;
  });
  let i = 0;
  return Object.keys(byType).sort().map((t) => {
    const s = byType[t];
    const errorRate = s.count ? s.errors / s.count : 0;
    const minsSinceLast = s.last ? (nowMs - new Date(s.last).getTime()) / 60000 : Infinity;
    let state = "running";
    if (errorRate >= th.downRate && s.count >= th.downMin) state = "down";
    else if (minsSinceLast > th.idleMins) state = "idle";
    const dirKeys = Object.keys(s.dirs);
    const dir = dirKeys.length > 1 ? "bi" : (dirKeys[0] || "bi");
    return {
      type: t, name: t, abbr: initials(t), abbrBg: ABBR_BG[(i++) % ABBR_BG.length],
      count: s.count, errors: s.errors, queue: s.queue,
      success: s.count ? ((s.count - s.errors) / s.count) * 100 : 100,
      latency: s.latN ? s.latSum / s.latN : 0,
      spark: s.spark.length ? s.spark : [s.count],
      last: s.last, errorRate: errorRate, state: state, dir: dir
    };
  });
}
// Theme palette as LITERAL colors (for markdown-element output — no CSS vars / classes available).
