  const cols = "grid-template-columns:1.7fr 1.1fr 1fr 1fr 0.9fr 0.55fr 1.1fr 1fr 16px";
  const lbl = `font:700 10px/1 -apple-system,BlinkMacSystemFont,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:${p.muted}`;
