      <div style="min-width:0"><div style="font-weight:700;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(s.name)}</div>
        <div style="font-size:11px;color:${p.muted}">Integration</div></div>
    </div>
    <div><span style="display:inline-block;border:1px solid ${p.border};border-radius:999px;padding:4px 12px;font-size:12px;color:${p.text}">${dirLabel}</span></div>
    <div style="${mono}">${fmtInt(rate)}<span style="color:${p.muted}">/min</span></div>
    <div style="${mono}">${lat}</div>
    <div style="${mono};color:${sCol};font-weight:700">${fmtPct(s.success)}</div>
    <div style="${mono}">${s.queue}</div>
    <div><svg viewBox="0 0 120 30" style="width:100%;max-width:140px;height:28px" preserveAspectRatio="none">
      <path d="${sparkPath(s.spark, 120, 28)}" fill="none" stroke="${hex}" stroke-width="2"/></svg></div>
    <div style="display:flex;align-items:center;gap:8px"><span style="width:9px;height:9px;border-radius:999px;display:inline-block;background:${hex}"></span>${stateLabel}</div>
    <div style="text-align:right;font-size:18px;line-height:1;color:${p.muted}">›</div>
  </div>`;
  return `<div style="background:${p.panel};border:1px solid ${p.border};border-radius:16px;padding:16px 18px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif">${header}${values}</div>`;
