data.query:
query ($s: DateTime, $e: DateTime, $errorState: [String!], $inProcessState: [String!]) {
  counts: integrationStaging(
    where: {processedAt: {_gte: $s, _lt: $e}}
    orderBy: [{field: integrationConfigId, direction: asc}]
  ) {
    edges {
      node {
        integrationConfig {
          integrationTypeId
          isInbound
        }
        _aggregate {
          id {
            count
          }
          processedAt {
            maximum
          }
        }
      }
    }
  }
  errorsByType: integrationStaging(
    where: {processedAt: {_gte: $s, _lt: $e}, _or: [{statusId: {_in: $errorState}}, {appPostError: {_eq: true}}]}
    orderBy: [{field: integrationConfigId, direction: asc}]
  ) {
    edges {
      node {
        integrationConfig {
          integrationTypeId
        }
        _aggregate {
          id {
            count
          }
        }
      }
    }
  }
  queueByType: integrationStaging(
    where: {processedAt: {_gte: $s, _lt: $e}, statusId: {_in: $inProcessState}}
    orderBy: [{field: integrationConfigId, direction: asc}]
  ) {
    edges {
      node {
        integrationConfig {
          integrationTypeId
        }
        _aggregate {
          id {
            count
          }
        }
      }
    }
  }
  sparkByType: integrationStaging(
    where: {processedAt: {_gte: $s, _lt: $e}}
    orderBy: [{field: integrationConfigId, direction: asc}]
  ) {
    edges {
      node {
        integrationConfig {
          integrationTypeId
        }
        processedAt(round: {unit: hour})
        _aggregate {
          id {
            count
          }
        }
      }
    }
  }
  latencySample: integrationStaging(
    orderBy: [{field: processedAt, direction: desc}]
    first: 1000
  ) {
    edges {
      node {
        createdAt
        processedAt
        integrationConfig {
          integrationTypeId
        }
      }
    }
  }
  runsSample: integrationStaging(
    orderBy: [{field: processedAt, direction: desc}]
    first: 300
  ) {
    edges {
      node {
        number
        processedAt
        statusId
        appPostError
        attemptCount
        internalRecordReference
        externalRecordReference
        createdAt
        integrationConfig {
          integrationTypeId
        }
      }
    }
  }
  configs: integrationConfiguration {
    edges {
      node {
        id
        name
        active
        isInbound
        parameters
        maxRetryAttemps
        maxRecords
        integrationTypeId
      }
    }
  }
}

