// Percent-encoding polyfill — the sandbox has no encodeURIComponent / btoa.
function encodeURIComponentPolyfill(str) {
  const unreserved = {};
  const safe = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_.~";
  for (let i = 0; i < safe.length; i++) unreserved[safe.charCodeAt(i)] = true;
  const out = [];
  const hex = (n) => { const h = n.toString(16).toUpperCase(); return h.length === 1 ? "0" + h : h; };
  for (let i = 0; i < str.length; i++) {
    const c = str.charCodeAt(i);
    if (c < 0x80) out.push(unreserved[c] ? str.charAt(i) : "%" + hex(c));
    else if (c < 0x800) out.push("%" + hex(0xC0 | (c >> 6)) + "%" + hex(0x80 | (c & 0x3F)));
    else if (c >= 0xD800 && c <= 0xDBFF) {
      const next = str.charCodeAt(i + 1);
      const cp = 0x10000 + ((c & 0x3FF) << 10) + (next & 0x3FF); i++;
      out.push("%" + hex(0xF0 | (cp >> 18)) + "%" + hex(0x80 | ((cp >> 12) & 0x3F)) +
               "%" + hex(0x80 | ((cp >> 6) & 0x3F)) + "%" + hex(0x80 | (cp & 0x3F)));
    } else out.push("%" + hex(0xE0 | (c >> 12)) + "%" + hex(0x80 | ((c >> 6) & 0x3F)) + "%" + hex(0x80 | (c & 0x3F)));
  }
  return out.join("");
}
