data.query:
query ($s: DateTime, $e: DateTime, $errorState: [String!]) {
  errors: integrationStaging(
    where: {
      processedAt: { _gte: $s, _lt: $e }
      _or: [
        { statusId: { _in: $errorState } }
        { appPostError: { _eq: true } }
      ]
    }
    orderBy: [{ field: processedAt, direction: desc }]
    first: 200
  ) {
    edges {
      node {
        number
        processedAt
        attemptCount
        statusId
        appPostError
        internalRecordReference
        response 
        integrationConfig {
          integrationTypeId
        }
      }
    }
  }
}

